int smb_send_rqst(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
	int ret = 0;
	int i;
	int cork = 1;
	struct kvec *iov;
	size_t total_len = 0;

	if (server == NULL || rqst == NULL || rqst->iov == NULL)
		return -EINVAL;

	if (server->sock == NULL)
		return -ENOTCONN;

	if (setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &cork, sizeof(cork)) < 0)
		return -errno;

	iov = rqst->iov;
	for (i = 0; i < rqst->nr_iovecs; i++)
		total_len += iov[i].iov_len;

	ret = smb_send_kvec(server, rqst->iov, rqst->nr_iovecs);
	if (ret < 0)
		goto out;

	for (i = 1; i < rqst->nr_pages; i++) {
		ret = smb_send_page(server, rqst->pages[i], rqst->offsets[i], rqst->offsets[i] + rqst->lengths[i]);
		if (ret < 0)
			goto out;
	}

out:
	cork = 0;
	setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &cork, sizeof(cork));

	if (ret < 0)
		server->tcp_status = -1;
	else if (ret != total_len)
		server->tcp_status = -1;

	if (ret < 0)
		printk(KERN_ERR "Failed to send SMB request: %d\n", ret);

	return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
	int ret = 0;
	int i;
	size_t total_len = 0;
	struct kvec *vec;
	struct page **pages;
	unsigned long offset;
	int nr_vec;

	if (!server || !server->ssocket) {
		pr_err("Invalid server or socket\n");
		return -EINVAL;
	}

	if (server->tcp_state == TCP_CLOSING)
		return -ENOTCONN;

	if (set_cork(server->ssocket, 1) < 0) {
		pr_err("Failed to cork socket\n");
		return -EIO;
	}

	vec = rqst->rq_iov;
	nr_vec = rqst->rq_nvec;
	pages = rqst->rq_pages;
	offset = rqst->rq_offset;
	total_len = rqst->rq_length;

	ret = smb_send_kvec(server, vec, nr_vec);
	if (ret < 0)
		goto uncork;

	for (i = 0; i < rqst->rq_npages; i++) {
		ret = smb_send_page(server, pages[i], offset, PAGE_SIZE);
		if (ret < 0)
			goto uncork;
		offset += ret;
	}

uncork:
	if (set_cork(server->ssocket, 0) < 0)
		pr_err("Failed to uncork socket\n");

	if (total_len != (size_t)ret) {
		server->tcp_status = TCP_RECONNECT;
		pr_err("Sent only %d bytes of %zu expected\n", ret, total_len);
		return -EIO;
	}

	return ret;
}

#include <netinet/tcp.h>
#include <linux/socket.h>

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst) {
    int ret = 0;
    int corked = 0;
    size_t total_len = 0;
    struct kvec *iov;
    int iov_idx;

    if (!server || !server->sock) {
        return -EINVAL;
    }

    /* Set TCP_CORK option */
    if (setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){1}, sizeof(int)) == 0) {
        corked = 1;
    }

    iov = rqst->rq_iov;
    for (iov_idx = 0; iov_idx < rqst->rq_nvec; iov_idx++) {
        total_len += iov[iov_idx].iov_len;
    }

    ret = smb_send_kvec(server, rqst->rq_iov, rqst->rq_nvec, 0);
    if (ret < 0) {
        goto out;
    }

    for (iov_idx = 1; iov_idx < rqst->rq_nvec; iov_idx++) {
        ret = smb_send_kvec(server, &rqst->rq_iov[iov_idx], 1, MSG_MORE);
        if (ret < 0) {
            goto out;
        }
    }

    /* Uncork the socket */
    if (corked) {
        setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){0}, sizeof(int));
        corked = 0;
    }

    /* Check if the total bytes sent match expected length */
    if (ret != total_len) {
        server->tcp_status = -1;
        ret = -EIO;
    }

out:
    if (corked) {
        setsockopt(server->sock, IPPROTO_TCP, TCP_CORK, &(int){0}, sizeof(int));
    }

    if (ret < 0) {
        // Log the error
    }

    return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
    int ret = 0;
    struct kvec *iov;
    int iov_count;
    int i;

    if (!server || !server->sock) {
        return -ENOTCONN;
    }

    if (set_sockopt_cork(server->sock, 1) < 0) {
        return -EFAULT;
    }

    iov = rqst->rq_iov;
    iov_count = rqst->rq_nvec;

    ret = smb_send_kvec(server->sock, iov, iov_count, 0);
    if (ret < 0) {
        goto uncork;
    }

    for (i = 0; i < rqst->rq_npages; i++) {
        ret = smb_sendpage(server->sock, rqst->rq_pages[i], 0, rqst->rq_pagecnt[i], MSG_MORE);
        if (ret < 0) {
            goto uncork;
        }
    }

    ret = 0;

uncork:
    set_sockopt_cork(server->sock, 0);
    if (ret < 0) {
        server->tcp_status = 0;
        cifs_dbg(VFS, "Failed to send SMB request: %d\n", ret);
    }

    return ret;
}

int send_smb_request(struct TCP_Server_Info *server, struct smb_rqst *rqst)
{
	int ret = 0;
	int total_sent = 0;
	struct kvec *iov = rqst->rq_iov;
	int iovcnt = rqst->rq_nvec;
	struct smb_hdr *hdr = (struct smb_hdr *)iov[0].iov_base;
	size_t total_len = iov[0].iov_len;
	struct msghdr msg = {0};
	unsigned long flags;

	if (!server || !server->ssock) {
		pr_err("Invalid server or socket\n");
		return -EINVAL;
	}

	if (setsockopt(server->ssock, IPPROTO_TCP, TCP_CORK, &(int){1}, sizeof(int)) < 0) {
		pr_err("Failed to cork socket\n");
		return -EIO;
	}

	ret = smb_send_kvec(server, iov, iovcnt, 0);
	if (ret < 0) {
		pr_err("Failed to send initial SMB request\n");
		goto uncork_and_out;
	}

	total_sent = ret;

	if (rqst->rq_npages) {
		int i;
		for (i = 0; i < rqst->rq_npages; i++) {
			ret = smb_sendpage(server, rqst->rq_pages[i], 0, rqst->rq_pages[i]->length, MSG_MORE);
			if (ret < 0) {
				pr_err("Failed to send SMB request pages\n");
				goto uncork_and_out;
			}
			total_sent += ret;
		}
	}

uncork_and_out:
	if (setsockopt(server->ssock, IPPROTO_TCP, TCP_CORK, &(int){0}, sizeof(int)) < 0)
		pr_err("Failed to uncork socket\n");

	if (total_sent != total_len) {
		server->tcp_status = -1;
		pr_err("Incomplete SMB request sent, reconnect required\n");
		ret = -EIO;
	}

	return ret;
}
